export const players:Player[]=raw.map((r,i)=>({id:String(i+1),name:r[0],positions:r[1].split('/') as Pos[],overall:r[2],offense:r[3],defense:r[4],shooting:r[5],passing:r[6],rebounding:r[7],stamina:r[8],teams:r[9].split('/'),tags:r[10].split('/'),aliases:playerAliases[r[0]]}));
export type Category={id:string;name:string;description:string;eligible:(p:Player)=>boolean};
export const categories:Category[]=[
{id:'mvp',name:'MVP Winner',description:'Won an NBA regular-season MVP',eligible:p=>p.tags.includes('mvp')},
{id:'champion',name:'NBA Champion',description:'Won an NBA championship',eligible:p=>p.tags.includes('champion')},
{id:'defense',name:'All-Defensive Selection',description:'Made an All-Defensive team',eligible:p=>p.tags.includes('defense')},
{id:'international',name:'International Player',description:'Born outside the United States (starter tags)',eligible:p=>p.tags.includes('international')},
{id:'neverallstar',name:'Never an All-Star',description:'Never selected to an NBA All-Star team',eligible:p=>!p.tags.includes('allstar')},
{id:'lakers',name:'Played for Lakers',description:'Played for the Los Angeles Lakers',eligible:p=>p.teams.includes('LAL')},
{id:'celtics',name:'Played for Celtics',description:'Played for the Boston Celtics',eligible:p=>p.teams.includes('BOS')},
{id:'bulls',name:'Played for Bulls',description:'Played for the Chicago Bulls',eligible:p=>p.teams.includes('CHI')},
{id:'knicks',name:'Played for Knicks',description:'Played for the New York Knicks',eligible:p=>p.teams.includes('NYK')},
{id:'spurs',name:'Played for Spurs',description:'Played for the San Antonio Spurs',eligible:p=>p.teams.includes('SAS')},
{id:'warriors',name:'Played for Warriors',description:'Played for the Golden State Warriors',eligible:p=>p.teams.includes('GSW')},
{id:'rockets',name:'Played for Rockets',description:'Played for the Houston Rockets',eligible:p=>p.teams.includes('HOU')},
{id:'90s',name:'1990s Star',description:'Played at a high level in the 1990s',eligible:p=>p.tags.includes('90s')},
{id:'00s',name:'2000s Star',description:'Played at a high level in the 2000s',eligible:p=>p.tags.includes('00s')},
{id:'10s',name:'2010s Star',description:'Played at a high level in the 2010s',eligible:p=>p.tags.includes('10s')},
{id:'20s',name:'2020s Player',description:'Played in the 2020s',eligible:p=>p.tags.includes('20s')},
{id:'guard',name:'Point Guard',description:'Primary or secondary point guard',eligible:p=>p.positions.includes('PG')},
{id:'wing',name:'Wing',description:'Shooting guard or small forward',eligible:p=>p.positions.includes('SG')||p.positions.includes('SF')},
{id:'big',name:'Big Man',description:'Power forward or center',eligible:p=>p.positions.includes('PF')||p.positions.includes('C')},
{id:'nonmvp',name:'Never Won MVP',description:'Never won the NBA regular-season MVP',eligible:p=>!p.tags.includes('mvp')},
{id:'ringless',name:'Never Won a Ring',description:'Never won an NBA title',eligible:p=>!p.tags.includes('champion')},
];
export const shuffle=<T,>(arr:T[]):T[]=>{const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
